#include <iostream>
#include <string>
#include <sstream>
#include <cmath>

int main() {
    std::string input_line;
    std::getline(std::cin, input_line);
    std::istringstream iss(input_line);
    std::string p_str, k_str;
    iss >> p_str >> k_str;
    int p = std::stoi(p_str);
    int k = std::stoi(k_str);
    const long long MOD = 1000000007;

    auto mod_pow = [](long long base, long long exp, long long mod) -> long long {
        long long result = 1;
        base %= mod;
        while (exp > 0) {
            if (exp & 1) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    };

    if (k == 0) {
        std::cout << mod_pow(p, p - 1, MOD) << std::endl;
    } else if (k == 1) {
        std::cout << mod_pow(p, p, MOD) << std::endl;
    } else {
        int cycle = 1;
        int i;
        for (i = 1; i <= p; ++i) {
            cycle = (static_cast<long long>(cycle) * k) % p;
            if (cycle == 1) {
                break;
            }
        }
        std::cout << mod_pow(p, (p - 1) / i, MOD) << std::endl;
    }
    return 0;
}

